'use strict';
const ASSET={rune:'@@rune@@',medal:'@@medal@@',journal:'@@journal@@'};
const paths={back:'m14 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',play:'m8 4 12 8-12 8z',pause:'M8 5v14M16 5v14',cards:'M6 6h13v15H6zM3 17V2h13',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',bookmark:'M6 3h12v19l-6-5-6 5z',sound:'M4 9h4l5-5v16l-5-5H4zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0zM6 10v2a6 6 0 0 0 12 0v-2m-6 8v4m-4 0h8',repeat:'M4 8a8 8 0 0 1 14-3l3 3m0-6v6h-6M20 16a8 8 0 0 1-14 3l-3-3m0 6v-6h6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',flag:'M5 22V3c4-4 10 4 14 0v10c-4 4-10-4-14 0',compass:'M12 2a10 10 0 1 0 0 20 10 10 0 1 0 0-20m4 6-3 5-5 3 3-5z',star:'m12 2 3 7 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',layers:'m12 3 10 6-10 6L2 9zm-10 10 10 6 10-6M2 17l10 6 10-6',down:'m6 9 6 6 6-6',clock:'M12 6v6l4 2M12 2a10 10 0 1 0 0 20 10 10 0 1 0 0-20',slow:'M4 15a7 7 0 0 1 14 0H4zm14-1h3v4h-3M6 19v2m9-2v2M2 14v3',menu:'M4 6h16M4 12h16M4 18h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 1 0 0-14m5 12 6 6',warning:'m12 3 10 18H2zm0 6v5m0 3v1'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.compass}"/></svg>`;
const img=(name,cls='')=>`<img src="${ASSET[name]}" alt="" class="${cls}">`;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenes=[
 ['horizon','Экспедиции','Выбор урока','Дневник, активная тема, экран телефона'],
 ['map','Карта экспедиции','Путь по главе','Осмысленный рельеф, текущая точка и ворота проверки'],
 ['intro1','Интро · смысл','Одна мысль','Текст, пример, встроенный вопрос'],
 ['intro2','Интро · форма','Фраза складывается','Появление формулы по частям'],
 ['intro3','Интро · ловушка','Внимание к детали','Ответ, короткий отклик и конкретная причина'],
 ['builder','Собрать фразу','Режим 01 / 06','Плитки, сохранение правильного начала, повтор'],
 ['listen','Послушать и выбрать','Режим 02 / 06','Реальное системное озвучивание, четыре смысла'],
 ['dictation','Собрать услышанное','Режим 03 / 06','Текст скрыт; целые слова в банке'],
 ['gap','Дополнить фразу','Режим 04 / 06','Один пропуск, устойчивые позиции ответов'],
 ['match','Найти пары','Режим 05 / 06','Четыре пары, пауза, стабильная сетка'],
 ['voice','Сказать и сравнить','Режим 06 / 06','Удержание, запись, нейтральная неопределённость'],
 ['checkpoint','Ворота проверки','Другой тип входа','Раскрытие створок вместо карточки старта'],
 ['probe','Контрольная точка','Самостоятельный шаг','Спокойная проверка без немедленного раскрытия ответа'],
 ['result','Итоги сессии','Возвращение с находками','Руны, результат и собранные слова'],
 ['chapter','Итоги проверки','Закреплённый рубеж','Сильные места, повторение, следующая глава'],
 ['world','Урок завершён','Большое завершение','Знак экспедиции, семь глав, следующий горизонт'],
 ['dict-list','Словарь A · журнал','Быстрый поиск','Максимум слов на экране, звук и закладка рядом'],
 ['dict-cards','Словарь B · карточки','Сосредоточиться на слове','Крупная карточка, переворот, быстрый выбор'],
 ['dict-journal','Словарь C · находки','Вспомнить контекст','Группы по экспедициям и раскрытие в потоке']
];
const journey=scenes.filter(s=>!s[0].startsWith('dict-')).map(s=>s[0]);
const modeIds=['builder','listen','dictation','gap','match','voice','probe'];
const WORDS=[
 {id:'I',word:'I',ipa:'/aɪ/',meaning:'я',definition:'Так вы называете себя, когда говорите от своего лица.',chapter:'Первые слова',found:'До этой экспедиции'},
 {id:'am',word:'am',ipa:'/æm/',meaning:'есть',definition:'После I соединяет вас с описанием. В русском такое «есть» обычно не произносят.',chapter:'Первые слова',found:'До этой экспедиции'},
 {id:'here',word:'here',ipa:'/hɪə/',meaning:'здесь',definition:'В том месте, где вы сейчас находитесь.',chapter:'Я здесь',found:'В этой экспедиции'},
 {id:'ready',word:'ready',ipa:'/ˈredi/',meaning:'готов',definition:'Всё подготовлено — можно начинать.',chapter:'Я здесь',found:'В этой экспедиции'}
];
const state={scene:'horizon',mapChapter:0,theme:0,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,unlocked:new Set(['I','am','here']),saved:new Set(),unread:new Set(),word:2,flipped:false,filter:'Все',query:'',tokens:[],chosen:null,verdict:null,tries:0,earned:0,awarded:new Set(),pairLeft:null,pairRight:null,matched:new Set(),matchStarted:0,matchElapsed:0,timerOn:true,paused:false,voice:'ready',voiceCaptured:false,audio:'idle',audioOff:false,recording:false,recordSource:null,result:'normal',probe:null};
let taskSnapshot=null;
let jobs=new Set(),frames=new Set(),focusBefore=null,matchTick=null,speechId=0,voiceJob=null,toastJob=null,returnTo='map';
const $=s=>document.querySelector(s);
function later(fn,ms,motion=false){const id=setTimeout(()=>{jobs.delete(id);fn()},motion&&state.reduced?0:ms);jobs.add(id);return id}
function stopAudio(){speechId++;if('speechSynthesis'in window)speechSynthesis.cancel();state.audio='idle'}
function cancelWork(){jobs.forEach(clearTimeout);jobs.clear();frames.forEach(cancelAnimationFrame);frames.clear();if(matchTick)clearInterval(matchTick);matchTick=null;stopAudio();state.recording=false;state.recordSource=null;$('#fx').innerHTML='';$('#toast').innerHTML=''}
const btn=(text,action,kind='primary')=>`<button class="${kind}" data-action="${action}">${text}</button>`;
function terrain(){return `<svg class="terrain" viewBox="0 0 300 340" aria-hidden="true"><defs><linearGradient id="land" x2=".7" y2="1"><stop stop-color="#8eaa7d"/><stop offset="1" stop-color="#244c3e"/></linearGradient></defs><path d="M-20 185 110 100 260 135 345 245 200 352 15 309z" fill="#244b40"/><path d="M-20 175 110 90 260 125 345 230 200 327 15 286z" fill="url(#land)"/><path d="m-5 196 116-79 139 29 70 75-120 76-169-33zM18 215l95-71 121 22 50 52-87 53-146-21zM50 227l68-58 97 18 33 30-52 37-108-16z" fill="none" stroke="#d5e3b2" stroke-opacity=".24" stroke-width="1"/><path d="m96 214 53-26 68 20-58 32z" fill="#193b30" opacity=".6"/><path d="M125 176v-62a31 31 0 0 1 62 0v76l-30 14z" fill="#4a7155"/><path d="M134 177v-61a22 22 0 0 1 44 0v68l-21 11z" fill="#b5c799"/><path d="M142 175v-57a14 14 0 0 1 28 0v60l-13 9z" fill="#48674d"/><path d="M157 120v59" stroke="#edcf90" stroke-width="2"/><circle cx="157" cy="114" r="6" fill="#ebca84"/><path d="m113 186 44-19 48 16-47 25z" fill="#76936b"/><path d="m113 186v9l45 23 47-27v-8l-47 25z" fill="#3e644b"/><path d="m36 262 26-37 12 50z" fill="#698d68"/><path d="m37 263 25-38 1 39z" fill="#8aab7a"/><path d="m226 263 16-33 17 36z" fill="#315b42"/></svg>`}
function portal(){return `<div class="expedition-art">${img('journal')}</div>`}
const known=()=>WORDS.filter(w=>state.unlocked.has(w.id));
function progress(){const i=Math.max(0,journey.indexOf(state.scene)-3);return `<div class="progress-track" aria-label="Путь экспедиции">${Array.from({length:12},(_,n)=>`<span class="${n<i?'past':n===i?'current':''}"></span>`).join('')}</div>`}
function header(){const dict=state.scene.startsWith('dict-');$('#app-header').innerHTML=`<div class="brand"><button class="brandmark" data-action="map" aria-label="Карта экспедиции">${icon('compass')}</button><div><h2>${dict?'Мои слова':'Экспедиции'}</h2><small>${dict?'Собрано в пути':'Урок 01 · Первые открытия'}</small></div></div><div class="meta"><span class="badge">EN · A1</span><button class="rune-pill" data-action="rune-info" aria-label="Руны за экспедицию: ${state.earned}">${img('rune')}<span>${state.earned}</span></button><button class="icon-button flat" data-action="dictionary" aria-label="Открыть словарь">${icon('book')}</button><button class="icon-button flat exit-preview" data-action="immersive" aria-label="Вернуть панель макетов">${icon('menu')}</button></div>`}
function footer(){if(state.scene==='horizon'){$('#footer').innerHTML=`<button data-action="dictionary">${icon('book')}Мои слова</button><button class="next" data-action="intro1">${icon('play')}Продолжить</button>`;return}const dict=state.scene.startsWith('dict-');const mode=modeIds.includes(state.scene);const intro=state.scene.startsWith('intro');const blocked=(mode&&state.verdict!=='success'&&state.scene!=='probe')||(intro&&state.verdict!=='success')||(state.scene==='probe'&&state.probe===null);$('#footer').innerHTML=`<button data-action="back" aria-label="Назад">${icon('back')}Назад</button>${state.scene==='voice'?`<button class="mic ${state.recording?'recording':''}" id="hold-mic" aria-label="Удерживайте, чтобы говорить. С клавиатуры удерживайте пробел." aria-pressed="${state.recording}">${icon('mic')}<span>${state.recording?'Говорите':'Удерживать'}</span></button><button class="voice-access" data-action="assist-voice" aria-label="Доступное управление записью">${icon('menu')}</button>`:mode?'':`<div class="footer-center"><strong>${dict?'Только встреченные слова':state.scene==='map'?'Глава '+(state.mapChapter+1)+' из 7':'В своём темпе'}</strong>${dict?`${state.saved.size} сохранено`:state.scene==='match'?'Точность важнее скорости':'Без спешки. Каждый шаг имеет смысл.'}</div>`}<button class="next" data-action="${dict?'close-dictionary':'next'}" ${blocked?'disabled':''}>${icon(dict?'check':'arrow')}${dict?'Готово':'Далее'}</button>`;if(state.scene==='voice')bindHold()}
const controls={horizon:['Другая тема','Открыть карту'],map:['Начать сессию','Контрольная точка','Словарь'],briefing:['Загрузка','Продолжить с места','Нет сети'],intro1:['Верно','Ошибка'],intro2:['Верно','Ошибка'],intro3:['Верно','Ошибка'],builder:['Верно','Ошибка','Новая карточка'],listen:['Верно','Ошибка','Аудио недоступно','Новая карточка'],dictation:['Верно','Ошибка','Аудио недоступно'],gap:['Верно','Ошибка','Новая карточка'],match:['Пауза','Завершить пары','Без таймера'],voice:['Удачный ответ','Неуверенное распознавание','Нет микрофона'],checkpoint:['Открыть ворота'],probe:['Завершить проверку'],result:['Новая награда','Уже получено','Без новых рун','Карточки'],chapter:['Закрепилось','Стоит повторить'],world:['Следующий урок'], 'dict-list':['Все слова','Пусто','Карточки B','Находки C'],'dict-cards':['Перевернуть','Следующее слово','Журнал A','Находки C'],'dict-journal':['Раскрыть группу','Журнал A','Карточки B']};
function controlsView(){$('#scene-controls').innerHTML=`<span class="label">СОСТОЯНИЯ</span>${(controls[state.scene]||[]).map((x,i)=>`<button data-demo="${i}">${x}</button>`).join('')}`}
function syncSceneLayout(){const frame=$('#frame');frame.dataset.scene=state.scene;frame.classList.toggle('practice-mode',modeIds.includes(state.scene))}
function render(scene=state.scene,reset=true){if(scene==='discover')scene='builder';if(scene==='briefing')scene='intro1';cancelWork();closeOverlay(false);state.scene=scene;if(reset){state.tokens=[];state.chosen=null;state.verdict=null;state.tries=0;state.pairLeft=null;state.pairRight=null;state.matched.clear();state.voice='ready';state.voiceCaptured=false;state.probe=null;state.audioOff=false;state.matchElapsed=0;state.paused=false}$('#scene-select').value=scene;syncSceneLayout();header();$('#main').innerHTML=views[scene]();$('#main').scrollTop=0;footer();controlsView();scheduleTaskFinding(scene);if(scene==='match')startMatchTimer();if(['result','chapter','world'].includes(scene))countResult();}
const views={
horizon:()=>`<div class="content portal-scene enter"><div class="portal-copy"><div class="eyebrow">Урок 1 · A1</div><h1>Сказать о себе</h1><p>Местоимение I и глагол am.<br>От первых фраз — к разговору.</p><div class="portal-bits">${'<span></span>'.repeat(7)}</div><div class="between"><small>7 глав</small><small>56 сессий</small></div><div style="height:24px"></div>${btn('Открыть маршрут '+icon('arrow'),'enter-world')}</div><div>${portal()}</div></div>`, 
map:()=>atlasMapView(),
intro1:()=>introView(0),intro2:()=>introView(1),intro3:()=>introView(2),
builder:()=>builderView(false),dictation:()=>builderView(true),
listen:()=>taskShell(`<div class="task-heading"><p>Послушайте и выберите смысл</p><h1>Что прозвучало?</h1></div>${audioControl('I am here')}<div class="options" id="options">${['Я готов','Я здесь','Я дома','Я там'].map((x,i)=>option(x,i,false)).join('')}</div><div id="feedback" class="feedback" aria-live="polite"></div>`),
gap:()=>taskShell(`<div class="task-heading"><p>Дополните фразу</p><div class="meaning">Я готов.</div></div><div class="gap-sentence"><span class="gap-slot" id="gap-slot">…</span> am ready.</div><div class="options" id="options">${['my','I','me','l'].map((x,i)=>option(x,i,true)).join('')}</div><div id="feedback" class="feedback" aria-live="polite"></div>`),
match:()=>taskShell(`<div class="task-heading"><p>Найдите четыре пары</p><h1>Слова узнают<br>друг друга.</h1></div><div class="between"><span class="timer">${icon('clock')}<span id="timer">${state.timerOn?'00:00':'Без таймера'}</span></span><button class="text-button" data-action="pause">${icon('pause')}Пауза</button></div><div class="match-grid">${[ ['here','готов'],['I','есть'],['ready','я'],['am','здесь'] ].map(([a,b])=>`<button class="pair target" data-pair-left="${a}">${a}</button><button class="pair" data-pair-right="${b}">${b}</button>`).join('')}</div><div id="feedback" class="feedback" aria-live="polite"><span id="pair-count">0 из 4 пар</span></div>`),
voice:()=>taskShell(`<div class="task-heading center"><p>Послушайте, затем скажите вслух</p><h1 class="voice-target">I am here.</h1><small>Я здесь.</small></div>${audioControl('I am here')}<div class="wave" id="voice-wave">${wave()}</div><div id="feedback" class="feedback center" aria-live="polite">Удерживайте микрофон внизу, пока говорите.</div><div class="voice-comparison hidden" id="voice-comparison"><button data-say="I am here">${icon('play')}Образец</button><button data-action="my-voice">${icon('sound')}Мой ответ</button></div>`),
checkpoint:()=>`<div class="checkpoint-classic enter"><div class="atlas-portal-art"><span class="atlas-portal-ring"></span><span class="atlas-portal-ring"></span><div class="atlas-portal">${icon('flag')}<div class="atlas-door left"></div><div class="atlas-door right"></div></div></div><div class="eyebrow">Глава ${state.mapChapter+1} · Контрольная точка</div><h1>Время увидеть,<br>чему вы научились.</h1><p>Знакомый материал в новых ситуациях.<br>Спокойно, в своём темпе.</p>${btn('Начать проверку '+icon('arrow'),'open-gate')}${btn('Вернуться на карту','map','secondary')}</div>`, 
probe:()=>taskShell(`<div class="task-heading"><div class="eyebrow" style="color:var(--metal);margin-bottom:17px">Самостоятельная проверка</div><p>Выберите фразу «Я готов»</p><h1>Ваш ответ.</h1></div><div class="options" id="options">${['I here am','I am ready','I ready am','Am I ready'].map((x,i)=>option(x,i,true)).join('')}</div><div id="feedback" class="feedback" aria-live="polite">Результат увидите после проверки.</div>`,false),
result:()=>resultView('session'),chapter:()=>resultView('chapter'),world:()=>resultView('world'),
'dict-list':()=>dictionaryList(),'dict-cards':()=>dictionaryCards(),'dict-journal':()=>dictionaryJournal()
};
function atlasMapView(){const points=atlasRoutes[state.mapChapter];const current=state.mapChapter===0?4:1;return `<div class="content restored-map enter"><h1>Местоимение I и глагол am</h1><nav class="chapter-selector" aria-label="Главы маршрута">${atlasRoutes.map((_,i)=>`<button data-atlas-chapter="${i}" class="${state.mapChapter===i?'active':''}" aria-pressed="${state.mapChapter===i}" aria-label="Глава ${i+1}">${i+1}</button>`).join('')}</nav><div class="map-caption"><b>Глава ${state.mapChapter+1} из 7</b><span>${current-1} из 8 сессий</span></div><div class="map-world">${atlasLandscape(state.mapChapter,true)}<svg class="map-path" viewBox="0 0 390 695" preserveAspectRatio="none" aria-hidden="true"><path class="route-base" d="${atlasCurve(points)}"/><path class="route-complete" d="${atlasCurve(points.slice(0,current))}"/><path class="route-light" d="${atlasCurve(points.slice(0,current))}"/></svg>${points.map(([x,y],i)=>{const done=i+1<current,active=i+1===current,checkpoint=i===7;return `<button class="map-node ${done?'done':active?'current':'locked'} ${checkpoint?'checkpoint-node':''}" style="left:${x/390*100}%;top:${y}px;--i:${i}" data-action="${checkpoint?'checkpoint':'intro1'}" aria-label="${checkpoint?'Контрольная точка':'Сессия '+(state.mapChapter*8+i+1)}"><span class="node-face">${icon(checkpoint?'flag':done?'check':active?'play':'lock')}</span>${active&&x<240?'<span class="node-callout">Вы здесь</span>':''}${done?'<span class="node-stars">'+icon('star').repeat(3)+'</span>':`<span class="node-ordinal">${checkpoint?'Проверка главы':String(state.mapChapter*8+i+1).padStart(2,'0')}</span>`}</button>`}).join('')}</div>${btn('Продолжить сессию '+(state.mapChapter*8+current)+' '+icon('arrow'),'intro1')}<button class="text-button" data-action="dictionary">${icon('book')}Мои слова</button></div>`}
function enterAtlasMap(){render('map');if(state.reduced)return;$('#fx').innerHTML=`<div class="map-passage"><div class="passage-glow"></div><div class="passage-preview">${atlasPortalWindow(state.mapChapter)}</div><div class="passage-title"><span>ГЛАВА ${state.mapChapter+1}</span><strong>Ваш маршрут начинается.</strong></div></div>`;later(()=>{$('#fx').innerHTML=''},1450,true)}
function introView(i){const data=[{k:'Смысл',title:'Начните с себя.',body:'Чтобы сказать что-то о себе, начните с <span class="target">I</span> — «я». После него поставьте <span class="target">am</span>. В русском «Я здесь» обходится без «есть», а английский оставляет это маленькое звено.',formula:['I','am','here'],q:'Какая фраза значит «Я здесь»?',options:['I here','I am here','Am here'],correct:1},{k:'Форма',title:'У каждого слова<br>своё место.',body:'В <span class="target">I am here</span> сначала говорящий, затем связующее слово, затем место. Сохраните порядок <span class="target">I → am → here</span> — и фраза уже готова.',formula:['I','am','here'],q:'Что ставится сразу после I?',options:['here','I','am'],correct:2},{k:'Ловушка',title:'Маленькое слово.<br>Большая разница.',body:'<span class="target">I here</span> выглядит коротко, но в этой фразе не хватает <span class="target">am</span>. Не заставляйте «я» перепрыгивать сразу в «здесь»: оставьте между ними связку.',formula:['I','am','here'],q:'Где am стоит на своём месте?',options:['I am here','I here am','Am here I'],correct:0}][i];return `<div class="content lesson-intro enter"><div class="travel-label"><span class="number">0${i+1}</span><div><div class="eyebrow">${data.k}</div><small>Первое открытие</small></div></div>${progress()}<h1>${data.title}</h1><div class="prose">${data.body}</div><div class="formula stagger">${data.formula.map((x,n)=>`${n?'<span class="eq">+</span>':''}<span class="token target">${x}</span>`).join('')}</div><p class="muted" style="font-size:13px">${data.q}</p><div class="options" id="options">${data.options.map((x,n)=>option(x,n,true)).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div></div>`}
function rail(){return `<aside class="word-rail" aria-label="Найденные карточки"><button class="pocket-icon ${state.unread.size?'has-unread':''}" data-action="pocket" aria-label="Открыть найденные карточки: ${known().length}">${icon('cards')}<span class="counter">${known().length}</span></button><small>Находки<br>в пути</small><div id="arrival-host"></div><button class="icon-button flat" style="width:40px;color:var(--error);margin-top:12px" data-action="report" aria-label="Сообщить об ошибке">${icon('flag')}</button></aside>`}
function taskShell(body,showProgress=true){return `<div class="content enter">${showProgress?progress():''}<div class="task-layout"><section class="task-body">${body}</section>${rail()}</div></div>`}
function option(text,i,target=false){return `<button class="option ${target?'target-choice':''}" data-option="${i}"><span class="key">${i+1}</span><span class="label">${text}</span></button>`}
function builderView(listen){const target=listen?'I am ready':'I am here';const words=listen?['ready','really','am','reading','I','red']:['here','am','he','I','her','hear'];return taskShell(`<div class="task-heading"><p>${listen?'Послушайте и соберите фразу':'Соберите фразу'}</p>${listen?'<h1>Сначала — звук.</h1>':'<h1>Я здесь.</h1>'}</div>${listen?audioControl(target):'<p class="muted" style="font-size:12px">Нажимайте на слова в нужном порядке.</p>'}<div class="answer-line" id="answer-line" aria-live="polite"><span class="placeholder">${listen?'Услышанные слова появятся здесь':'Ваша фраза'}</span></div><div class="tile-bank" id="tile-bank">${words.map((w,i)=>`<button class="tile" data-token="${w}" data-token-index="${i}">${w}</button>`).join('')}</div><div id="feedback" class="feedback" aria-live="polite"></div>`)}
function audioControl(text){return `<div class="audio-field"><span style="width:38px"></span><button class="play" data-say="${text}" aria-label="Воспроизвести образец">${icon('play')}</button><button class="slow" data-slow="${text}" aria-label="Послушать медленнее">${icon('slow')}</button></div><div class="audio-status" id="audio-status" aria-live="polite">Нажмите, чтобы послушать</div>`}
function wave(){return Array.from({length:20},(_,i)=>`<i style="--h:${10+((i*7)%37)}px;--d:${i*.035}s"></i>`).join('')}
function dictionaryTop(letter,title,sub){return `<div class="dictionary-header"><div class="between"><span class="eyebrow">Словарь · Вариант ${letter}</span><span class="badge">${known().length} встречено</span></div><h1>${title}</h1><p class="muted" style="font-size:12px">${sub}</p></div>`}
function saveButton(w){return `<button data-save="${w.id}" class="${state.saved.has(w.id)?'saved':''}" aria-label="${state.saved.has(w.id)?'Убрать закладку':'Сохранить'} ${w.word}" aria-pressed="${state.saved.has(w.id)}">${icon('bookmark')}</button>`}
function wordRow(w,letter=true){return `<div class="word-row">${letter?`<span class="letter">${w.word[0].toUpperCase()}</span>`:''}<button class="body" style="text-align:left" data-word="${w.id}"><h3>${w.word}</h3><p>${w.ipa} · ${w.meaning}</p></button><div class="tools"><button data-say="${w.word}" aria-label="Послушать ${w.word}">${icon('sound')}</button>${saveButton(w)}</div></div>`}
function filteredWords(){return known().filter(w=>(state.filter!=='Сохранённые'||state.saved.has(w.id))&&(!state.query||`${w.word} ${w.meaning}`.toLowerCase().includes(state.query.toLowerCase())))}
function dictionaryList(){return `<div class="content enter">${dictionaryTop('A','Журнал слов.','Все находки — в одном спокойном списке.')}<input class="search" id="dictionary-search" aria-label="Найти слово" placeholder="Слово или перевод" value="${esc(state.query)}"><div class="chips">${['Все','Сохранённые'].map(x=>`<button class="${state.filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}<button data-action="dict-cards">Карточками ${icon('arrow')}</button></div><div id="word-list">${wordRowsMarkup()}</div><p class="variant-note">A · Быстрее всего найти конкретное слово. Звук и закладка доступны сразу, без раскрытия.</p></div>`}
function wordRowsMarkup(){const words=filteredWords();return words.length?words.map(w=>wordRow(w)).join(''):'<div class="empty">Здесь пока нет слов.<br>Новые находки появятся во время экспедиции.</div>'}
function cardMarkup(w){return `<div class="field-card-stage"><div class="field-card ${state.flipped?'flipped':''}" id="field-card" role="button" tabindex="0" aria-label="Перевернуть карточку ${w.word}" data-action="flip-word"><div class="face front"><span class="eyebrow">Найдено в пути · EN</span><div><h2>${w.word}</h2><small>${w.ipa}</small></div><small>Коснитесь, чтобы перевернуть</small></div><div class="face back"><span class="eyebrow">Значение</span><h2>${w.meaning}</h2><small>Слово остаётся с вами</small></div></div></div>`}
function detailMarkup(w){return `<div class="word-detail">${cardMarkup(w)}<p>${w.definition}</p><div class="tools"><button class="secondary" data-say="${w.word}">${icon('sound')}Послушать</button><button class="secondary ${state.saved.has(w.id)?'saved':''}" data-save="${w.id}" aria-pressed="${state.saved.has(w.id)}">${icon('bookmark')}<span>${state.saved.has(w.id)?'Сохранено':'Сохранить'}</span></button></div></div>`}
function selectedWord(){const words=known();return words.find(w=>w.id===WORDS[state.word]?.id)||words[0]}
function dictionaryCards(){const w=selectedWord();return `<div class="content enter">${dictionaryTop('B','Одно слово.<br>Всё внимание.','Крупная карточка, произношение и смысл.')}<div id="card-detail">${detailMarkup(w)}</div><div class="thumbs">${known().map(w=>`<button class="${w.id===selectedWord().id?'active':''}" data-select-word="${w.id}">${w.word}</button>`).join('')}</div><p class="variant-note">B · Удобнее рассмотреть и запомнить одну находку. Выбор слова не теряет место в журнале.</p></div>`}
function dictionaryJournal(){return `<div class="content enter">${dictionaryTop('C','Вспомнить,<br>где встретились.','Слова хранят не только значение, но и историю встречи.')}<div class="chips"><button data-action="dict-list">${icon('search')}Найти слово</button><button data-action="saved-filter">Сохранённые · ${state.saved.size}</button></div>${['Я здесь','Первые слова'].map((group,i)=>`<details class="journal-group" ${i===0?'open':''}><summary><span class="stamp">0${i+1}</span><span class="body"><h3>${group}</h3><small>${i===0?'Текущая экспедиция':'Ранее встречено'} · ${known().filter(w=>w.chapter===group).length} слова</small></span>${icon('down')}</summary><div class="group-body">${known().filter(w=>w.chapter===group).map(w=>wordRow(w,false)).join('')}</div></details>`).join('')}<p class="variant-note">C · Контекст помогает вспомнить слово. Группы раскрываются прямо в списке; незнакомые будущие слова не показываются.</p></div>`}
function resultView(kind){const chapter=kind==='chapter',world=kind==='world';const amount=state.result==='none'?0:state.result==='received'?state.earned:state.earned;return `<div class="content center enter" style="max-width:530px"><div class="eyebrow" style="color:var(--metal)">${world?'Урок завершён':chapter?'Контрольная точка завершена':'Экспедиция завершена'}</div><div class="result-seal" style="margin-top:20px">${world?icon('compass'):chapter?icon('flag'):img('medal')}</div><h1 class="result-title">${world?'Маршрут пройден.<br>Можно дальше.':chapter?'Есть на что<br>опереться.':'Вернулись<br>с чем-то новым.'}</h1><p class="muted" style="font-size:13px">${world?'Семь глав позади. Впереди — новый горизонт.':chapter?'Вот что получилось и к чему стоит вернуться.':'Практика закончилась. Умение осталось.'}</p><div class="rune-result">${img('rune')}<div style="text-align:left"><strong id="rune-count" data-amount="${amount}">${state.result==='new'?'+':''}0</strong><small>${state.result==='received'?'рун уже получено':state.result==='none'?'новых рун':'рун за экспедицию'}</small></div></div>${state.result==='received'?'<p class="variant-note" style="margin:0 auto">Повторный просмотр результата не начисляет награду ещё раз.</p>':''}<div class="metrics"><div><strong>${chapter?'3 / 4':'92%'}</strong><small>${chapter?'уверенных ответов':'точность · демо'}</small></div><div><strong>${world?'7':'4:32'}</strong><small>${world?'глав':'время · демо'}</small></div><div><strong>${known().length}</strong><small>слова с вами</small></div></div>${chapter?`<div class="stack" style="text-align:left;margin-bottom:24px"><div class="hint-strip">${icon('check')}Порядок слов закрепился.</div><button class="list-link" data-action="builder">${icon('repeat')}<span>Ещё раз собрать фразу</span>${icon('arrow')}</button></div>`:`<div class="findings">${known().map(w=>`<button data-word="${w.id}">${w.word}</button>`).join('')}</div>`}${btn(world?'Следующий горизонт '+icon('arrow'):chapter?'Открыть новую главу '+icon('arrow'):'Продолжить путь '+icon('arrow'),world?'new-world':chapter?'new-chapter':'map')}<button class="text-button" data-action="dictionary" style="margin-top:13px">${icon('book')}Посмотреть находки</button></div>`}
function countResult(){const el=$('#rune-count');if(!el)return;const target=Number(el.dataset.amount);const start=performance.now();const prefix=state.result==='received'||state.result==='none'?'':'+';function tick(now){const t=state.reduced?1:Math.min(1,(now-start)/1400);el.textContent=prefix+Math.round(target*(1-Math.pow(1-t,3)));if(t<1){const id=requestAnimationFrame(n=>{frames.delete(id);tick(n)});frames.add(id)}}tick(start)}
function award(){if(!state.awarded.has(state.scene)){state.awarded.add(state.scene);state.earned+=state.tries===0?3:state.tries===1?2:1;header()}}
function feedback(success,text){const el=$('#feedback');if(!el)return;el.className=`feedback ${success?'success':'error'}`;el.innerHTML=`<div class="verdict">${icon(success?'check':'repeat')}${success?'Получилось.':'Попробуйте ещё раз.'}</div>${text}`;state.verdict=success?'success':'error';if(success&&modeIds.includes(state.scene)&&state.scene!=='probe')award();footer()}
function choose(index){if(state.verdict==='success')return;state.chosen=index;let correct=1;if(state.scene.startsWith('intro'))correct=[1,2,0][Number(state.scene.slice(-1))-1];const buttons=[...document.querySelectorAll('#options .option')];buttons.forEach(b=>b.classList.remove('wrong','correct','selected','shake'));if(state.scene==='probe'){state.probe=index;buttons[index].classList.add('selected');$('#feedback').textContent='Ответ выбран. Можно продолжить.';footer();return}const ok=index===correct;buttons[index]?.classList.add(ok?'correct':'wrong');if(!ok){buttons[index]?.classList.add('shake');state.tries++}if(state.scene==='gap')$('#gap-slot').textContent=['my','I','me','l'][index];let copy='';if(state.scene==='listen'){copy=ok?'I am here.':index===0?'«Я готов» — это I am ready. Здесь прозвучало here: «здесь».':index===2?'«Я дома» называет дом. В записи here — «здесь», без уточнения места.':'«Я там» указывает на другое место. Here значит «здесь», рядом с говорящим.'}else if(state.scene==='gap'){copy=ok?'I am ready.':index===0?'My значит «мой». Когда говорите о себе, начните с I — «я».':index===2?'Me тоже относится к вам, но перед am здесь нужна форма I.':'Это маленькая буква l. Английское «я» пишется большой I.'}else{copy=ok?'Да. Этот порядок сохраняет связь слов.':'Начните с I, затем поставьте am, а после — here.'}feedback(ok,copy)}
function addToken(word,index){if(state.verdict==='success'||state.tokens.length>=3)return;const button=$(`[data-token-index="${index}"]`);if(button?.classList.contains('used'))return;state.verdict=null;state.tokens.push({word,index});renderTokens();const expected=state.scene==='dictation'?['I','am','ready']:['I','am','here'];if(state.tokens.length===expected.length){const ok=state.tokens.every((t,i)=>t.word===expected[i]);if(!ok){state.tries++;$('#answer-line').classList.add('shake')}feedback(ok,ok?'':`<button class="retry-button" data-action="retry-build">${icon('repeat')}Собрать ещё раз</button>`)}}
function renderTokens(){const line=$('#answer-line');line.classList.remove('shake');line.innerHTML=state.tokens.length?state.tokens.map((t,i)=>`<button class="slot-token" data-remove-token="${i}" aria-label="Убрать ${t.word}">${t.word}</button>`).join(''):'<span class="placeholder">Ваша фраза</span>';document.querySelectorAll('[data-token-index]').forEach(b=>{const used=state.tokens.some(t=>t.index===Number(b.dataset.tokenIndex));b.classList.toggle('used',used);b.disabled=used});footer()}
function retryBuild(){const expected=state.scene==='dictation'?['I','am','ready']:['I','am','here'];let prefix=0;while(prefix<state.tokens.length&&state.tokens[prefix].word===expected[prefix])prefix++;state.tokens=state.tokens.slice(0,prefix);state.verdict=null;renderTokens();$('#feedback').className='feedback';$('#feedback').innerHTML='Верное начало осталось на месте.'}
function scheduleTaskFinding(scene){
 const word={builder:'here',listen:'here',dictation:'ready',gap:'ready',match:'ready',voice:'here'}[scene];
 if(!word)return;
 const animate=scene==='builder'||!state.unlocked.has(word);
 if(!animate)return;
 later(()=>{if(state.scene===scene&&!$('#overlay').children.length)unlock(word,true)},650);
}
function unlock(id,animate=false){const fresh=!state.unlocked.has(id);state.unlocked.add(id);if(fresh)state.unread.add(id);const button=$('.pocket-icon');if(button){button.classList.toggle('has-unread',state.unread.size>0);button.setAttribute('aria-label',`Открыть найденные карточки: ${known().length}`);button.querySelector('.counter').textContent=known().length}if(animate&&$('#arrival-host')){$('#arrival-host').innerHTML=`<div class="arrival">${icon('cards')}</div>`;later(()=>{if($('#arrival-host'))$('#arrival-host').innerHTML=''},1200,true)}if(fresh)announce(`${id}: карточка добавлена в находки`,true)}
function announce(text,quiet=false){if(toastJob){clearTimeout(toastJob);jobs.delete(toastJob)}if(quiet){$('#toast').textContent='';$('#toast').setAttribute('aria-label',text);return}$('#toast').innerHTML=`<div class="toast">${esc(text)}</div>`;toastJob=later(()=>{$('#toast').innerHTML=''},3000)}
function speak(text,slow=false){if(state.audioOff){audioUnavailable();return}if(!('speechSynthesis'in window)){audioUnavailable();return}stopAudio();const id=speechId;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-GB';utterance.rate=slow?.72:.92;state.audio='playing';audioUI();const finish=()=>{if(id!==speechId)return;state.audio='idle';audioUI()};utterance.onend=finish;utterance.onerror=()=>{if(id!==speechId)return;state.audio='unavailable';audioUI()};speechSynthesis.speak(utterance);later(()=>{if(id===speechId&&state.audio==='playing'){speechSynthesis.cancel();state.audio='unavailable';audioUI()}},8000)}
function audioUI(){document.querySelectorAll('.play').forEach(b=>{const active=state.audio==='playing';b.classList.toggle('playing',active);b.innerHTML=icon(active?'pause':'play');b.setAttribute('aria-label',active?'Остановить образец':'Воспроизвести образец');b.disabled=state.audioOff});const label=$('#audio-status');if(label)label.textContent=state.audio==='playing'?'Слушайте…':state.audio==='unavailable'?'Аудио сейчас недоступно. Можно продолжить.':'Послушать ещё раз';}
function audioUnavailable(){stopAudio();state.audioOff=true;state.audio='unavailable';audioUI();document.querySelectorAll('.slow').forEach(b=>b.disabled=true)}
function startMatchTimer(){if(matchTick)clearInterval(matchTick);state.matchStarted=performance.now()-state.matchElapsed;matchTick=setInterval(()=>{if(state.scene!=='match'||state.paused||!state.timerOn||document.hidden||state.verdict==='success')return;state.matchElapsed=performance.now()-state.matchStarted;const el=$('#timer');if(el){const sec=Math.floor(state.matchElapsed/1000);el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}},250)}
function selectPair(side,value){if(state.paused||state.verdict==='success')return;const word=side==='left'?value:WORDS.find(w=>w.meaning===value)?.id;if(state.matched.has(word))return;state[side==='left'?'pairLeft':'pairRight']=value;document.querySelectorAll(`[data-pair-${side}]`).forEach(b=>b.classList.toggle('selected',b.dataset[side==='left'?'pairLeft':'pairRight']===value));if(state.pairLeft&&state.pairRight){const left=state.pairLeft,right=state.pairRight;const a=$(`[data-pair-left="${left}"]`),b=$(`[data-pair-right="${right}"]`);if(WORDS.find(w=>w.id===left)?.meaning===right){state.matched.add(left);a.classList.add('matched');b.classList.add('matched');a.disabled=true;b.disabled=true;$('#feedback').textContent=`${state.matched.size} из 4 пар`;if(state.matched.size===4){feedback(true,'Все четыре пары найдены.');if(matchTick)clearInterval(matchTick)}}else{a.classList.add('shake');b.classList.add('shake');state.tries++;$('#feedback').textContent='Эти слова из разных пар. Попробуйте снова.';later(()=>{a.classList.remove('shake');b.classList.remove('shake')},400,true)}a.classList.remove('selected');b.classList.remove('selected');state.pairLeft=null;state.pairRight=null}}
function bindHold(){const b=$('#hold-mic');if(!b)return;b.addEventListener('pointerdown',e=>{if(e.button!==0||state.recording)return;e.preventDefault();b.setPointerCapture(e.pointerId);startVoice('pointer')});b.addEventListener('pointerup',()=>finishVoice('pointer'));b.addEventListener('pointercancel',()=>cancelVoice());b.addEventListener('lostpointercapture',()=>{if(state.recordSource==='pointer')cancelVoice()});b.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(!e.repeat)startVoice('keyboard')}});b.addEventListener('keyup',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();finishVoice('keyboard')}});b.addEventListener('blur',()=>{if(state.recordSource==='keyboard')cancelVoice()})}
function startVoice(source){if(state.recording||state.voice==='processing'||state.verdict==='success')return;stopAudio();state.recording=true;state.recordSource=source;state.voice='recording';const b=$('#hold-mic');b?.classList.add('recording');b?.setAttribute('aria-pressed','true');if(b)b.querySelector('span').textContent='Говорите';$('#voice-wave')?.classList.add('active');$('#feedback').textContent='Говорите до отпускания кнопки. Микрофон макета не записывает звук.';document.querySelectorAll('.play,.slow').forEach(x=>x.disabled=true)}
function finishVoice(source){if(!state.recording||source!==state.recordSource)return;state.recording=false;state.recordSource=null;state.voice='processing';const b=$('#hold-mic');b?.classList.remove('recording');b?.setAttribute('aria-pressed','false');if(b)b.querySelector('span').textContent='Удерживать';$('#voice-wave')?.classList.remove('active');$('#feedback').textContent='Сопоставляем ответ…';voiceJob=later(()=>{state.voice='complete';state.voiceCaptured=true;$('#voice-comparison')?.classList.remove('hidden');document.querySelectorAll('.play,.slow').forEach(x=>x.disabled=false);feedback(true,'Демонстрация: фраза распознана. Сравните образец и свой ответ.')},700,true)}
function cancelVoice(){if(!state.recording)return;state.recording=false;state.recordSource=null;state.voice='ready';$('#voice-wave')?.classList.remove('active');if($('#feedback'))$('#feedback').textContent='Запись прервана. Можно попробовать снова.';document.querySelectorAll('.play,.slow').forEach(x=>x.disabled=false);footer()}
function closeOverlay(restore=true){if(restore&&state.scene==='match'){state.paused=false;state.matchStarted=performance.now()-state.matchElapsed}$('#overlay').innerHTML='';$('#main').inert=false;$('#footer').inert=false;$('#app-header').inert=false;if(restore&&focusBefore?.isConnected)focusBefore.focus();focusBefore=null}
function overlay(title,body,type='modal'){const oldFocus=focusBefore||document.activeElement;closeOverlay(false);focusBefore=oldFocus;if(state.scene==='match')state.paused=true;$('#main').inert=true;$('#footer').inert=true;$('#app-header').inert=true;$('#overlay').innerHTML=`<div class="${type==='drawer'?'drawer-scrim':'modal-scrim'}"><section class="${type}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="head"><h2 id="dialog-title">${title}</h2><button class="icon-button flat" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${body}</section></div>`;$('#overlay button')?.focus()}
function openPocket(wordId){if(state.scene==='match'){state.paused=true}if(state.recording)cancelVoice();stopAudio();audioUI();state.unread.clear();$('.pocket-icon')?.classList.remove('has-unread');if(wordId)state.word=WORDS.findIndex(w=>w.id===wordId);state.flipped=false;const w=selectedWord();overlay('Находки в пути.',`<div class="between"><span class="eyebrow">${known().length} встречено</span><small>${state.saved.size} сохранено</small></div><div id="pocket-detail">${detailMarkup(w)}</div><div class="thumbs">${known().map(x=>`<button class="${x.id===w.id?'active':''}" data-pocket-word="${x.id}">${x.word}</button>`).join('')}</div><div class="hint-strip">${icon('compass')}Шаг и ваш ответ сохранены на экране.</div>${btn('Вернуться к заданию','resume-pocket','secondary')}`,'drawer')}
function saveWord(id){if(state.saved.has(id))state.saved.delete(id);else state.saved.add(id);document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{const saved=state.saved.has(id);b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',`${saved?'Убрать закладку':'Сохранить'} ${id}`);const label=b.querySelector('span');if(label)label.textContent=saved?'Сохранено':'Сохранить'});if(state.scene==='dict-list'&&state.filter==='Сохранённые')$('#word-list').innerHTML=wordRowsMarkup();if(state.scene.startsWith('dict-'))footer();announce(state.saved.has(id)?'Слово сохранено в ваши карточки':'Закладка убрана')}
function transition(next){render(next);$('#fx').innerHTML='<div class="transition"><div class="shutter"></div><div class="shutter right"></div><div class="travel-line"></div></div>';later(()=>{$('#fx').innerHTML=''},1000,true)}
function next(){if(state.scene.startsWith('dict-')){returnFromDictionary();return}if(state.scene==='probe'){state.result='normal';render('chapter');return}const i=journey.indexOf(state.scene);render(journey[Math.min(i+1,journey.length-1)])}
const themeLabels={dark:'Forest',gold:'Black Gold',olive:'Olive',midnight:'Midnight',ember:'Ember',aurora:'Aurora',volt:'Volt',indigo:'Indigo',sagePorcelain:'Sage Porcelain'};
function applyTheme(key){const t=APP_THEMES[key]||APP_THEMES.indigo;state.theme=key;const tokens={bg:t.bgPrimary,card:t.bgCard,surface:t.bgSurface,raised:t.bgSurface2,text:t.textPrimary,muted:t.textMuted,accent:t.accent,metal:t.gold,line:t.borderLight,error:t.wrong,correct:t.correct,'on-accent':t.correctText,'on-metal':t.textOnGold,'accent-bg':t.accentBg,'correct-bg':t.correctBg,'error-bg':t.wrongBg};Object.entries(tokens).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));$('#theme-select').value=key;try{localStorage.setItem('phraseman-expedition-preview-theme',key)}catch{} }
function setTheme(delta=1){const keys=Object.keys(APP_THEMES);applyTheme(keys[(keys.indexOf(state.theme)+delta+keys.length)%keys.length])}
function openCatalog(){if(state.scene==='match')state.paused=true;$('#catalog-root').innerHTML=`<section class="catalog" role="dialog" aria-modal="true" aria-labelledby="catalog-title"><div class="content"><div class="between"><div><div class="eyebrow">Phraseman · Expedition studies</div><h1 id="catalog-title" class="serif" style="margin-top:12px">Вся экспедиция.</h1></div><button class="icon-button" data-action="close-catalog" aria-label="Закрыть каталог">${icon('close')}</button></div><p class="muted" style="font-size:12px;margin-top:15px">20 экранов · 6 механик · 3 варианта словаря. Выберите точку или пройдите путь по порядку.</p><div class="catalog-grid">${scenes.map((s,i)=>`<button class="catalog-tile" data-scene="${s[0]}"><span class="index">${String(i+1).padStart(2,'0')} · ${s[2]}</span><span><strong>${s[1]}</strong><small>${s[3]}</small></span></button>`).join('')}</div></div></section>`;$('#frame').inert=true;$('.studio-bar').inert=true;$('#catalog-root button').focus()}
function closeCatalog(){if(state.scene==='match'){state.paused=false;state.matchStarted=performance.now()-state.matchElapsed}$('#catalog-root').innerHTML='';$('#frame').inert=false;$('.studio-bar').inert=false;$('.studio-bar [data-action=catalog]')?.focus()}
function openDictionary(){if(!state.scene.startsWith('dict-')){returnTo=state.scene;stopAudio();audioUI();if(state.recording)cancelVoice();const keys=['tokens','chosen','verdict','tries','pairLeft','pairRight','matched','matchElapsed','timerOn','voice','voiceCaptured','probe','audioOff'];taskSnapshot={scene:state.scene,html:$('#main').innerHTML,scroll:$('#main').scrollTop,data:Object.fromEntries(keys.map(k=>[k,k==='matched'?new Set(state[k]):Array.isArray(state[k])?[...state[k]]:state[k]]))};}state.filter='Все';state.query='';render('dict-list')}
function returnFromDictionary(){if(!taskSnapshot){render(returnTo);return}cancelWork();closeOverlay(false);const snap=taskSnapshot;taskSnapshot=null;Object.assign(state,snap.data,{scene:snap.scene,paused:false});$('#scene-select').value=state.scene;syncSceneLayout();$('#main').innerHTML=snap.html;$('#main').scrollTop=snap.scroll;header();footer();controlsView();if(state.scene==='match')startMatchTimer()}
function action(name){if(name==='briefing')name='intro1';if(views[name]){if(name.startsWith('dict-')&&!state.scene.startsWith('dict-'))returnTo=state.scene;render(name);return}switch(name){
case 'catalog':openCatalog();break;case 'close-catalog':closeCatalog();break;case 'immersive':document.body.classList.toggle('immersive');break;case 'reduce':state.reduced=!state.reduced;document.body.classList.toggle('reduce',state.reduced);$('#motion-toggle').setAttribute('aria-pressed',String(state.reduced));break;
case 'theme-next':setTheme(1);break;case 'theme-prev':setTheme(-1);break;case 'enter-world':enterAtlasMap();break;case 'start':transition('intro1');break;case 'open-gate':transition('probe');break;
case 'next':next();break;case 'back':if(state.scene.startsWith('dict-'))returnFromDictionary();else render(journey[Math.max(0,journey.indexOf(state.scene)-1)]);break;
case 'dictionary':openDictionary();break;case 'close-dictionary':returnFromDictionary();break;
case 'pocket':openPocket();break;case 'close':case 'resume-pocket':closeOverlay();if(state.scene==='match'){state.paused=false;state.matchStarted=performance.now()-state.matchElapsed}break;
case 'flip-word':state.flipped=!state.flipped;$('#field-card')?.classList.toggle('flipped',state.flipped);break;
case 'retry-build':retryBuild();break;
case 'pause':state.paused=true;overlay('Небольшая остановка.',`<p>Пары и время останутся на месте. Продолжите, когда будете готовы.</p>${btn('Продолжить','resume-match')}${btn('Начать пары заново','restart-match','secondary')}${btn('Убрать таймер','untimed','secondary')}`);break;
case 'resume-match':closeOverlay();state.paused=false;state.matchStarted=performance.now()-state.matchElapsed;break;case 'restart-match':render('match');break;case 'untimed':state.timerOn=false;closeOverlay();state.paused=false;$('#timer').textContent='Без таймера';break;
case 'assist-voice':overlay('Запись без удержания.',`<p>Равнозначный вариант для управления с клавиатуры или экранного диктора. Нажмите «Начать», а затем завершите запись отдельной кнопкой.</p>${btn('Начать запись','assist-start')}`);break;
case 'assist-start':closeOverlay();startVoice('assist');$('#feedback').innerHTML='Идёт демонстрация записи.<br><button class="retry-button" data-action="assist-stop">Завершить запись</button>';break;case 'assist-stop':finishVoice('assist');break;
case 'my-voice':announce('В макете показан образец состояния. Настоящая запись не создавалась.');break;
case 'rune-info':overlay('Руны за ваш путь.',`${img('rune')}<p>В макете: 3 руны за чистый первый ответ, 2 — за второй, 1 — за последующие. Повторное открытие экрана не начисляет их снова.</p><p>Баланс приложения не меняется.</p>${btn('Понятно','close')}`);break;
case 'report':overlay('Сообщить об ошибке.',`<p>Какой момент требует внимания?</p><button class="list-link" data-action="report-done">Текст или перевод ${icon('arrow')}</button><button class="list-link" data-action="report-done">Аудио или произношение ${icon('arrow')}</button><button class="list-link" data-action="report-done">Работа интерфейса ${icon('arrow')}</button>`);break;case 'report-done':closeOverlay();announce('Предпросмотр подтверждения. Сообщение не отправлено.');break;
case 'new-chapter':overlay('Глава 02 открыта.',`<div class="chapter-stamp">02</div><h2 class="center">Можно идти дальше.</h2><p>Новый участок маршрута. Знакомые слова остаются с вами.</p>${btn('Вернуться на карту','map')}`);break;case 'new-world':transition('horizon');announce('Следующий урок: предпросмотр того же маршрута.');break;
case 'saved-filter':state.filter='Сохранённые';render('dict-list');break;
}}
function demo(i){const s=state.scene;if(s==='horizon')action(i?'enter-world':'theme-next');else if(s==='map')action(['intro1','checkpoint','dictionary'][i]);else if(s==='briefing'){if(i===0){overlay('Готовим маршрут.',`<div class="loading-route"><i></i><i></i><i></i></div><p>Собираем материалы перед первым шагом.</p>${btn('Отменить','close','secondary')}`);later(()=>{if($('#dialog-title')?.textContent==='Готовим маршрут.')overlay('Всё готово.',`<p>Материалы на месте. Пора отправляться.</p>${btn('Начать','start')}`)},1800)}else if(i===1)overlay('Продолжим отсюда.',`<div class="chapter-stamp">04</div><p>Ваш последний шаг — сборка фразы. Начало и находки сохранены.</p>${btn('Продолжить','builder')}`);else overlay('Маршрут подождёт.',`<p>Нет соединения для загрузки новых материалов. Уже доступные материалы и слова остаются с вами.</p>${btn('Попробовать ещё раз','briefing')}${btn('Открыть слова','dictionary','secondary')}`)}else if(s.startsWith('intro'))choose(i===0?[1,2,0][Number(s.slice(-1))-1]:[0,0,1][Number(s.slice(-1))-1]);else if(s==='discover'){if(i===2)openPocket();else{const id=i===0?'ready':'here';state.unlocked.delete(id);unlock(id,true)}}else if(s==='builder'||s==='dictation'){if(i===2){if(s==='dictation')audioUnavailable();else unlock('ready',true);return}state.tokens=[];state.verdict=null;const phrase=i===0?(s==='dictation'?['I','am','ready']:['I','am','here']):['am','I',s==='dictation'?'ready':'here'];phrase.forEach(w=>{const b=$(`[data-token="${w}"]`);addToken(w,Number(b.dataset.tokenIndex))})}else if(s==='listen'||s==='gap'){if(i===2){if(s==='listen')audioUnavailable();else unlock('ready',true)}else if(i===3)unlock('ready',true);else{state.verdict=null;choose(i===0?1:0)}}else if(s==='match'){if(i===0)action('pause');else if(i===2)action('untimed');else{WORDS.forEach(w=>{selectPair('left',w.id);selectPair('right',w.meaning)})}}else if(s==='voice'){document.querySelectorAll('.play,.slow').forEach(x=>x.disabled=false);if(voiceJob)clearTimeout(voiceJob);state.recording=false;state.recordSource=null;$('#voice-wave')?.classList.remove('active');if(i===0){state.voiceCaptured=true;$('#voice-comparison').classList.remove('hidden');feedback(true,'Демонстрация: ответ получился.')}else{state.verdict=null;state.voice=i===1?'uncertain':'unavailable';$('#feedback').className='feedback center';$('#feedback').innerHTML=i===1?'Не удалось уверенно разобрать речь. Это не ошибка.<br>Попробуйте ещё раз.':'Микрофон недоступен. Используйте доступное управление или продолжите просмотр через каталог.';footer()}}else if(s==='checkpoint')action('open-gate');else if(s==='probe'){state.probe=1;next()}else if(s==='result'){if(i===3)openPocket();else{state.result=['normal','received','none'][i];render('result')}}else if(s==='chapter'){overlay(i===0?'Уверенная опора.':'Повторим спокойно.',`<p>${i===0?'Порядок I → am → описание вы выбираете увереннее.':'Здесь стоит ещё раз услышать фразу и собрать её своими руками.'}</p>${btn(i===0?'Продолжить путь':'Вернуться к фразе',i===0?'close':'builder')}`)}else if(s==='world')action('new-world');else if(s==='dict-list'){if(i===0){state.filter='Все';state.query='';render()}else if(i===1){state.query='невстреченное';render()}else action(i===2?'dict-cards':'dict-journal')}else if(s==='dict-cards'){if(i===0)action('flip-word');else if(i===1){const list=known();state.word=WORDS.indexOf(list[(list.indexOf(selectedWord())+1)%list.length]);state.flipped=false;render('dict-cards')}else action(i===2?'dict-list':'dict-journal')}else if(s==='dict-journal'){if(i===0){const d=$('details');d.open=!d.open}else action(i===1?'dict-list':'dict-cards')}}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-action="flip-word"]');if(!el)return;if(el.dataset.atlasChapter!==undefined){state.mapChapter=Number(el.dataset.atlasChapter);render('map');return}if(el.dataset.scene){closeCatalog();render(el.dataset.scene);return}if(el.dataset.demo!==undefined){demo(Number(el.dataset.demo));return}if(el.dataset.action){action(el.dataset.action);return}if(el.dataset.option!==undefined){choose(Number(el.dataset.option));return}if(el.dataset.token){addToken(el.dataset.token,Number(el.dataset.tokenIndex));return}if(el.dataset.removeToken!==undefined){state.tokens.splice(Number(el.dataset.removeToken),1);state.verdict=null;renderTokens();$('#feedback').textContent='';return}if(el.dataset.say){if(el.classList.contains('playing')){stopAudio();audioUI()}else speak(el.dataset.say);return}if(el.dataset.slow){speak(el.dataset.slow,true);return}if(el.dataset.pairLeft){selectPair('left',el.dataset.pairLeft);return}if(el.dataset.pairRight){selectPair('right',el.dataset.pairRight);return}if(el.dataset.save){saveWord(el.dataset.save);return}if(el.dataset.word){openPocket(el.dataset.word);return}if(el.dataset.selectWord){state.word=WORDS.findIndex(w=>w.id===el.dataset.selectWord);state.flipped=false;render('dict-cards');return}if(el.dataset.pocketWord){state.word=WORDS.findIndex(w=>w.id===el.dataset.pocketWord);openPocket(el.dataset.pocketWord);return}if(el.dataset.filter){state.filter=el.dataset.filter;render('dict-list')}});
document.addEventListener('input',e=>{if(e.target.id==='dictionary-search'){state.query=e.target.value;$('#word-list').innerHTML=wordRowsMarkup()}});
$('#scene-select').innerHTML=scenes.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('');$('#scene-select').addEventListener('change',e=>render(e.target.value));$('#width-select').addEventListener('change',e=>{$('#frame').style.width=e.target.value==='full'?'100%':`min(${e.target.value}px,100%)`});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#catalog-root').children.length)closeCatalog();else if($('#overlay').children.length)action('close');else if(document.body.classList.contains('immersive'))document.body.classList.remove('immersive');return}if((e.key==='Enter'||e.key===' ')&&document.activeElement?.id==='field-card'){e.preventDefault();action('flip-word')}const dialog=$('#catalog-root [role=dialog]')||$('#overlay [role=dialog]');if(e.key==='Tab'&&dialog){const all=[...dialog.querySelectorAll('button,input,[tabindex="0"]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus()}}});
document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('paused',document.hidden);if(document.hidden){stopAudio();audioUI();cancelVoice();if(state.scene==='match'){state.paused=true}}else if(state.scene==='match'&&state.verdict!=='success'){action('pause')}});
$('#theme-select').innerHTML=Object.entries(themeLabels).map(([key,label])=>`<option value="${key}">${label}</option>`).join('');$('#theme-select').addEventListener('change',e=>applyTheme(e.target.value));let initialTheme='indigo';try{initialTheme=localStorage.getItem('phraseman-expedition-preview-theme')||initialTheme}catch{}applyTheme(initialTheme);document.body.classList.toggle('reduce',state.reduced);$('#motion-toggle').setAttribute('aria-pressed',String(state.reduced));const requested=location.hash.slice(1);const initial=requested==='discover'?'builder':requested==='briefing'?'intro1':requested;render(scenes.some(s=>s[0]===initial)?initial:'horizon');
